import type { OmarchyColors } from "@/features/material/colors";
import { makeThemeFileWriter } from "../shared";
import { hexFromArgb } from "@material/material-color-utilities";
import { flow } from "effect";

export const writeHyprlandLua = makeThemeFileWriter(
  "hyprland.lua",
  (input: OmarchyColors) => /* lua */ `
--
-- Generated by Omaterial for Omarchy v4.
--

-- Direction the light comes from, in degrees: 0 = right, 90 = top,
-- counter-clockwise. The shadow is cast on the opposite side.
local omaterial_light_angle = 90
local omaterial_shadow_distance = 8
local omaterial_shadow_vector = {
  -math.cos(math.rad(omaterial_light_angle)) * omaterial_shadow_distance,
  math.sin(math.rad(omaterial_light_angle)) * omaterial_shadow_distance, -- screen y points down
}

hl.config({
  general = {
    gaps_in = 2,
    gaps_out = 4,
    border_size = 1,
    col = {
      active_border = { colors = { "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_primary)}", "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_outline)}" }, angle = 55 },
      inactive_border = "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_outlineVariant)}"
    },
  },

  group = {
    col = {
      border_active = { colors = { "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_primary)}", "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_outline)}" }, angle = 55 },
      border_inactive = "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_outlineVariant)}",
    },
  },

  decoration = {
    blur = {
      enabled = true,
      size = 6,
      passes = 3,
      popups = true,
      -- Blur everything behind the scratchpad (special workspace).
      special = true,
    },
    shadow = {
      enabled = true,
      color = "${flow(hexFromArgb, (hex) => hex + "4d", hexToHyprlandRgb)(input.omaterial_shadow)}",
      color_inactive = "${flow(hexFromArgb, (hex) => hex + "1a", hexToHyprlandRgb)(input.omaterial_shadow)}",
      range = 60,
      offset = omaterial_shadow_vector,
      render_power = 4,
      scale = 1
    }
  },

  group = {
    groupbar = {
      enabled = true,
      render_titles = true,
      height = 24,
      gaps_in = 1,
      gaps_out = 2,
      keep_upper_gap = false,
      indicator_height = 0,
      indicator_gap = 0,
      text_padding = 8,

      -- Fill: opaque gradient boxes, square corners.
      gradients = true,
      gradient_rounding = 0,
      gradient_round_only_edges = false,
      round_only_edges = false,
      blur = true,

      text_color = "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_onSecondaryContainer)}",
      text_color_inactive = "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_onSurface)}",
      col = {
        active = "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_secondaryContainer)}",
        inactive = "${flow(hexFromArgb, hexToHyprlandRgb)(input.omaterial_surfaceContainer)}"
      },
    },
  }
})

-- Every shell surface is its own layer: bar, panels (omarchy-keyboard-panel),
-- notifications, OSD, menu, polkit, clipboard, emojis, reminders. Tooltips
-- and dropdowns are popups of the bar, covered by blur_popups. Each surface
-- paints its card at background-alpha 0.9. Menu-style layers (launcher,
-- clipboard, emojis, polkit) are full-screen with a 0.32 scrim, so
-- ignore_alpha sits between scrim and card: the card blurs, the scrim and
-- the transparent parts do not.
hl.layer_rule({
  match = {
    namespace = "^omarchy-(bar|keyboard-panel|notifications|osd|menu|polkit|clipboard|emojis|reminders)$",
  },
  blur = true,
  blur_popups = true,
  ignore_alpha = 0.5,
})

-- Smart gaps: drop the gaps when a single plain tiled window fills the
-- workspace. A group counts as one tiled window (w[t1]), so w[tg0] (zero
-- tiled groups) is added to keep groups gapped; otherwise the tab bar would
-- sit flush against the top bar.
local omaterial_lone_window = "w[t1] w[tg0]"

hl.workspace_rule({ workspace = omaterial_lone_window, gaps_out = 0, gaps_in = 0 })
hl.workspace_rule({ workspace = "f[1]", gaps_out = 0, gaps_in = 0 })

-- Drop border and rounding on lone window so it sits flush against the edges.
hl.window_rule({
  match = { float = false, workspace = omaterial_lone_window },
  border_size = 0,
  rounding = 0,
})

hl.window_rule({
  match = { float = false, workspace = "f[1]" },
  border_size = 0,
  rounding = 0,
})
`,
);

const hexToHyprlandRgb = (hex: string) => {
  const code = hex.replace(/^#/, "");
  return code.length === 6 ? `rgb(${code})` : `rgba(${code})`;
};
